// Reuse the real page-helper harness generated by the array regression.
await import('./test-rance10-array.mjs');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const build = path.join(root, 'build/rance10-tests');
const read = name => fs.readFileSync(path.join(root, 'xsystem4', name), 'utf8');
function func(file, name) {
  const text = read(file), m = new RegExp(`^(?:static )?[^\\n;{}]*\\b${name}\\([^;{}]*\\)\\s*\\{`, 'm').exec(text);
  assert.ok(m, name);
  let end = text.indexOf('{', m.index), depth = 0;
  do { if (text[end] === '{') depth++; if (text[end] === '}') depth--; end++; } while (depth);
  return text.slice(m.index, end);
}
let prefix = fs.readFileSync(path.join(build, 'array-test.c'), 'utf8').split('/* Generic Array ABI')[0];
prefix = prefix.replace('int marker; const char *text;', 'int marker,size; const char *text;')
  .replace('struct ain_variable { struct ain_type type; };', 'struct ain_variable { struct ain_type type; char *name; };')
  .replace('struct test_structure {struct ain_variable', 'struct test_structure {char *name;struct ain_variable');
const header = read('subprojects/libsys4/include/system4/savefile.h');
const source = `${prefix}
#define assert(c) do{if(!(c))__builtin_trap();}while(0)
#define ain_struct test_structure
#define GSAVE7_EMPTY_STRING 0x7fffffff
${header.slice(header.indexOf('struct gsave {'), header.indexOf('struct gsave *gsave_create'))}
void *xrealloc_array(void *p,size_t old,size_t count,size_t size){(void)old;return p?xrealloc(p,count*size):xcalloc(count,size);}
char *strdup(const char *s){size_t n=0;while(s[n])n++;char *p=xmalloc(n+1);memcpy(p,s,n+1);return p;}
int alloc_struct(int no){struct page *p=alloc_page(STRUCT_PAGE,no,program.structures[no].nr_members);for(int i=0;i<p->nr_vars;i++)p->values[i]=variable_initval(program.structures[no].members[i].type.data);return heap_alloc_page(p);}
union vm_value vm_int(int value){return (union vm_value){.i=value};}
${['gsave_add_array','gsave_add_string','gsave_add_record','gsave_add_keyval','gsave_add_struct_def','gsave_get_struct_def','gsave_validate_value'].map(n=>func('subprojects/libsys4/src/savefile.c',n)).join('\n')}
static int32_t add_value_to_gsave(enum ain_data_type type,union vm_value val,struct gsave *save);
${func('src/savedata.c','collect_flat_arrays')}
${func('src/savedata.c','add_value_to_gsave')}
${func('src/savedata.c','struct_member_index')}
static union vm_value gsave_to_vm_value(struct gsave *save,enum ain_data_type type,int struct_type,int array_rank,int32_t value);
bool game_rance10_cn;
${func('src/savedata.c','savedata_repair_legacy_config')}
${func('src/savedata.c','gsave_load_array')}
${func('src/savedata.c','gsave_to_vm_value')}
#define CHECK(c) do{if(!(c))return __LINE__;}while(0)
struct gsave saved={.version=7};
int run_tests(void){
 next_slot=1;used=allocated=freed=0;
 union vm_value dims={.i=3};struct page *p=alloc_array(1,&dims,AIN_ARRAY_INT,-1,false);
 p->values[0].i=41;p->values[1].i=-9;p->values[2].i=5;int original=heap_alloc_page(p);
 int index=add_value_to_gsave(AIN_ARRAY,(union vm_value){.i=original},&saved);
 CHECK(index==0&&saved.arrays[index].flat_arrays[0].type==AIN_INT&&gsave_validate_value(index,AIN_ARRAY,&saved));
 int loaded=gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,index).i;
 CHECK(heap[loaded].page!=p&&heap[loaded].page->a_type==AIN_ARRAY_INT&&heap[loaded].page->nr_vars==3);
 CHECK(heap[loaded].page->values[0].i==41&&heap[loaded].page->values[1].i==-9&&heap[loaded].page->values[2].i==5);
 heap[loaded].page->values[0].i=0;CHECK(p->values[0].i==41);heap_unref(loaded);heap_unref(original);
 dims.i=2;p=alloc_array(1,&dims,AIN_ARRAY_STRING,-1,false);struct string text={.size=3,.text="abc"};
 heap[p->values[0].i].s=&text;original=heap_alloc_page(p);index=add_value_to_gsave(AIN_ARRAY,(union vm_value){.i=original},&saved);
 loaded=gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,index).i;
 CHECK(heap[loaded].page->a_type==AIN_ARRAY_STRING&&heap[loaded].page->nr_vars==2);
 CHECK(!strcmp(heap_get_string(heap[loaded].page->values[0].i)->text,"abc")&&!strcmp(heap_get_string(heap[loaded].page->values[1].i)->text,""));
 heap_unref(loaded);heap_unref(original);
 original=heap_alloc_page(NULL);index=add_value_to_gsave(AIN_ARRAY,(union vm_value){.i=original},&saved);
 loaded=gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,index).i;CHECK(heap[loaded].page==NULL);heap_unref(loaded);heap_unref(original);
 loaded=gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,-1).i;CHECK(heap[loaded].page==NULL&&gsave_validate_value(-1,AIN_ARRAY,&saved));heap_unref(loaded);
 CHECK(!gsave_validate_value(-1,AIN_ARRAY_INT,&saved)&&!gsave_validate_value(saved.nr_arrays,AIN_ARRAY,&saved));
 CHECK(add_value_to_gsave(AIN_DELEGATE,(union vm_value){.i=12345},&saved)==0);
 CHECK(gsave_validate_value(2,AIN_ENUM,&saved));
 loaded=gsave_to_vm_value(&saved,AIN_DELEGATE,-1,0,12345).i;CHECK(heap[loaded].page==NULL);heap_unref(loaded);
 // Rance 10 saves transient object-reference arrays, including allocated
 // zero-length arrays. References use the existing -1 save sentinel.
 for(int n=0;n<2;n++){
  dims.i=n?2:0;p=alloc_array(1,&dims,AIN_REF_STRUCT,7,false);original=heap_alloc_page(p);
  index=add_value_to_gsave(AIN_ARRAY,(union vm_value){.i=original},&saved);
  CHECK(saved.arrays[index].flat_arrays[0].type==AIN_REF_STRUCT);
  loaded=gsave_to_vm_value(&saved,AIN_ARRAY,7,1,index).i;
  CHECK(heap[loaded].page->a_type==AIN_REF_STRUCT&&heap[loaded].page->array.struct_type==7&&heap[loaded].page->nr_vars==dims.i);
  for(int i=0;i<dims.i;i++)CHECK(heap[loaded].page->values[i].i==-1);
  heap_unref(loaded);heap_unref(original);
 }
 int scalar[]={AIN_LONG_INT,AIN_FUNC_TYPE},storage[]={AIN_ARRAY_LONG_INT,AIN_ARRAY_FUNC_TYPE};
 for(int n=0;n<2;n++){
  dims.i=1;p=alloc_array(1,&dims,storage[n],-1,false);p->values[0].i=4321;original=heap_alloc_page(p);
  index=add_value_to_gsave(AIN_ARRAY,(union vm_value){.i=original},&saved);
  loaded=gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,index).i;
  CHECK(heap[loaded].page->a_type==storage[n]&&heap[loaded].page->values[0].i==4321);
  heap_unref(loaded);heap_unref(original);
 }
 return 0;
}
void error_case(int no){gsave_to_vm_value(&saved,AIN_ARRAY,-1,1,no==0?-2:saved.nr_arrays);}
`;
fs.writeFileSync(path.join(build, 'savedata-test.c'), source);
const compiler = process.env.RANCE10_TEST_CLANG || path.resolve(root, '../android-build/sdk/ndk/27.2.12479018/toolchains/llvm/prebuilt/windows-x86_64/bin/clang.exe');
const wasm = path.join(build, 'savedata-test.wasm');
const r = spawnSync(compiler, ['--target=wasm32-unknown-unknown','-x','c','-std=gnu11','-O1','-fno-builtin','-nostdlib','-Werror','-Wl,--no-entry','-Wl,--export=run_tests','-Wl,--export=error_case','-o',wasm,'-'], { input: source, encoding: 'utf8', env: { ...process.env, TEMP: build, TMP: build } });
assert.equal(r.status, 0, r.stderr || r.stdout);
const { instance } = await WebAssembly.instantiate(fs.readFileSync(wasm), {env:{vm_error(line){throw new WebAssembly.RuntimeError(`VM error at C line ${line}: ${source.split('\n')[line-1]}`);}}});
const line = instance.exports.run_tests();
assert.equal(line, 0, `C failure at ${line}: ${source.split('\n')[line - 1]}`);
for (let i = 0; i < 2; i++) assert.throws(() => instance.exports.error_case(i), WebAssembly.RuntimeError);
console.log('PASS: real gsave round-trips generic scalar/string/reference arrays (including empty), recovers omitted arrays, rebuilds transient delegates, rejects invalid indices.');
